const MODULE_ID = "salvage-union-dice";
const TEX = `modules/${MODULE_ID}/textures`;
const range = (a, b) => Array.from({ length: b - a + 1 }, (_, i) => a + i);

// Salvage Union "Scrapyard" dice. Each face is a full-bleed weathered sky-blue salvage-crate tile with
// a stamped dark frame and a rust-orange Typo Draft numeral, baked into the texture (variant "full" —
// colour lives in the art). Generated by tools/build_su_dice.py from the exact DSN face polygons.
Hooks.once("init", () => console.log(`${MODULE_ID} | init`));

Hooks.once("diceSoNiceReady", async (dice3d) => {
  console.log(`${MODULE_ID} | registering Salvage Union dice`);

  dice3d.addSystem({ id: MODULE_ID, name: "Salvage Union" }, "preferred");

  // Full-face art bakes the look in; the colorset only needs to match the body/bevels so the chamfer
  // strips blend with the faces. material "plastic" = matte/diffuse — the right default for baked full
  // textures (metal/chrome/glass add reflections that wash out the painted art).
  dice3d.addColorset(
    {
      name: "salvage-union",
      description: "Scrapyard",
      category: "Salvage Union",
      foreground: "#f4f1ea",   // chat-result text tint (faces are images)
      background: "#8cc7d6",   // weathered sky-blue body / bevel fill
      edge: "#1b2327",
      outline: "#10161a",
      material: "stone",       // matte stone — renders the full baked textures cleanly (no plastic)
      font: "Arial"
    },
    "preferred"
  );

  // labels[i] = face value i+1. Full-bleed faces + parallel engraving heightmaps.
  const registerDie = (type, shape, names) =>
    dice3d.addDicePreset(
      {
        type,
        system: MODULE_ID,
        colorset: "salvage-union",
        labels: names.map((n) => `${TEX}/${n}.webp`),
        bumpMaps: names.map((n) => `${TEX}/${n}-bump.webp`)
      },
      shape
    );

  registerDie("d6", "d6", range(1, 6).map((n) => `d6f${n}`));
  registerDie("d8", "d8", range(1, 8).map((n) => `d8f${n}`));
  // d10 atlas faces are d10f1="0" .. d10f10="9"; order so value 1->"1" .. value 10->"0".
  registerDie("d10", "d10", [...range(2, 10), 1].map((n) => `d10f${n}`));
  registerDie("d12", "d12", range(1, 12).map((n) => `d12f${n}`));
  registerDie("d20", "d20", range(1, 20).map((n) => `d20f${n}`));

  // d4 — each physical face shows 3 numerals; the full triangular face art (d4f1..d4f4) already has its
  // triplet baked in DSN's exact layout, so we feed them as per-value `backgrounds`. `labels` MUST be
  // present for DSN to process backgrounds — keep them transparent so no extra numerals are drawn.
  dice3d.addDicePreset(
    {
      type: "d4",
      system: MODULE_ID,
      colorset: "salvage-union",
      labels: range(1, 4).map(() => `${TEX}/d4blank.webp`),
      backgrounds: {
        labels: range(1, 4).map((n) => `${TEX}/d4f${n}.webp`),
        bumpMaps: range(1, 4).map((n) => `${TEX}/d4f${n}-bump.webp`)
      }
    },
    "d4"
  );
});
